spec.init_script:
const query = Document.prototype.querySelector, queries = Document.prototype.querySelectorAll;
Document.prototype.querySelector=function(s){return query.call(this,s)||query.call(this,'#lshell')?.shadowRoot?.querySelector(s)||null;};
Document.prototype.querySelectorAll=function(s){const own=queries.call(this,s);return own.length?own:(query.call(this,'#lshell')?.shadowRoot?.querySelectorAll(s)||own);};
const timeout=window.setTimeout;window.setTimeout=(fn,delay,...args)=>[2600,44000,45000,110000,190000].includes(delay)?0:timeout(fn,delay,...args);
